_CLOSURE_JSON = zlib.decompress(bytes.fromhex(_CLOSURE_ZLIB_HEX)).decode()
CLOSURE_SHA256 = '0038172d793ad07d55eb1af34bc4d26dfdcf81198f9b2934a516eb5b958359d0'
if hashlib.sha256(_CLOSURE_JSON.encode()).hexdigest() != CLOSURE_SHA256:
    raise RuntimeError("embedded KDA closure identity differs")
_CLOSURE = json.loads(_CLOSURE_JSON)

class GeneratedProgramDispatchError(ValueError):
    """Frozen KDA dispatch evidence is incomplete, inconsistent, or tampered."""


def _canonical_sha256(value: object) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def _object(value: object, fields: set[str], label: str) -> Mapping[str, object]:
    if not isinstance(value, Mapping) or set(value) != fields:
        actual = set(value) if isinstance(value, Mapping) else type(value).__name__
        raise GeneratedProgramDispatchError(
            f"{label} fields differ: expected {sorted(fields)!r}, got {actual!r}"
        )
    return value


def _nonempty_string(value: object, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise GeneratedProgramDispatchError(f"{label} must be a non-empty string")
    return value


def _ordered_fields(value: object, label: str, *, scalar: bool = False, allow_empty: bool = False):
    if not isinstance(value, list) or (not value and not allow_empty):
        raise GeneratedProgramDispatchError(f"{label} must be an ordered list")
    result, names = [], set()
    for index, item in enumerate(value):
        field = _object(item, {"name", "dtype"}, f"{label}[{index}]")
        name = _nonempty_string(field["name"], f"{label}[{index}].name")
        dtype = _nonempty_string(field["dtype"], f"{label}[{index}].dtype")
        if name in names or (scalar and dtype not in _SCALAR_DTYPES):
            raise GeneratedProgramDispatchError(f"{label} contains an invalid field")
        names.add(name)
        result.append(field)
    return result


def _torch_dtype_name(value: Any) -> str:
    name = str(value.dtype).removeprefix("torch.")
    if not name:
        raise GeneratedProgramDispatchError("tensor dtype is unavailable")
    return name


def _tensor_contract(value: Any) -> dict[str, object]:
    return {
        "dtype": _torch_dtype_name(value),
        "shape": [int(dim) for dim in value.shape],
        "stride": [int(dim) for dim in value.stride()],
        "storage_offset": int(value.storage_offset()),
    }


def _storage_pointer(value: Any) -> int:
    return int(value.untyped_storage().data_ptr())


def _storage_span(contract):
    shape, stride, offset = contract["shape"], contract["stride"], contract["storage_offset"]
    if any(dim == 0 for dim in shape):
        return None
    lower = upper = int(offset)
    for dim, step in zip(shape, stride, strict=True):
        extent = (int(dim) - 1) * int(step)
        lower += min(0, extent)
        upper += max(0, extent)
    return lower, upper


def _tensor_content_sha256(value: Any) -> str:
    import torch
    contiguous = value.detach().contiguous().view(torch.uint8).cpu()
    payload = bytes(contiguous.flatten().tolist())
    digest = hashlib.sha256()
    digest.update(json.dumps(_tensor_contract(value), sort_keys=True, separators=(",", ":")).encode())
    digest.update(b"\0")
    digest.update(payload)
    return digest.hexdigest()


class _ProgramPrepared:
    """One exact prepared KDA row; hot launches contain no preparation work."""

    __slots__ = (
        "_closed",
        "_cuda_graph",
        "_cuda_graph_capture_stream",
        "_cuda_graph_warmed",
        "_device",
        "_host_stages",
        "_host_actions",
        "_inner",
        "_binding_facts",
        "_stage_roles",
        "_tensors",
        "_use_cuda_graph",
        "_workspaces",
    )

    def __init__(
        self,
        inner: Any,
        *,
        topology: str,
        host_stages: tuple[Mapping[str, object], ...],
        tensors: Mapping[str, Any],
        workspaces: Mapping[str, Any],
        binding_recipes: Mapping[str, Mapping[str, object]],
    ) -> None:
        if not tensors:
            raise GeneratedProgramDispatchError("prepared KDA closure has no tensor device root")
        self._inner = inner
        self._host_stages = host_stages
        stage_roles = {
            "single": ("main",),
            "bt16": ("prepare", "main"),
            "affine": ("affine_main", "affine_map", "affine_scan", "affine_correction"),
        }.get(topology)
        if stage_roles is None:
            raise GeneratedProgramDispatchError(f"prepared KDA topology {topology!r} is unknown")
        self._stage_roles = stage_roles
        self._tensors = dict(tensors)
        self._workspaces = dict(workspaces)
        self._device = next(iter(tensors.values())).device
        facts: dict[str, Mapping[str, object]] = {}
        for namespace, values in (("tensor", tensors), ("workspace", workspaces)):
            for name, value in values.items():
                recipe = binding_recipes.get(name)
                if not isinstance(recipe, Mapping):
                    raise GeneratedProgramDispatchError(
                        f"prepared KDA slot {name!r} has no immutable materialization recipe"
                    )
                facts[name] = MappingProxyType(
                    {
                        "namespace": namespace,
                        **_tensor_contract(value),
                        "data_ptr": int(value.data_ptr()),
                        "storage_data_ptr": _storage_pointer(value),
                        "materialization_op": recipe.get("op"),
                        "semantic_source": recipe.get("source"),
                        "alias_identity": recipe.get("alias_identity"),
                    }
                )
        self._binding_facts = MappingProxyType(facts)
        actions: list[tuple[object, ...]] = []
        for stage in host_stages:
            role = stage["role"]
            if role == "beta_tma_refresh":
                source_base = self._value(stage["source"])
                source_contract = stage["source_view_contract"]
                source = source_base.as_strided(
                    tuple(int(value) for value in source_contract["shape"]),
                    tuple(int(value) for value in source_contract["stride"]),
                    int(source_contract["storage_offset"]),
                )
                target_base = self._value(stage["target"])
                target_contract = stage["target_view_contract"]
                target = target_base.as_strided(
                    tuple(int(value) for value in target_contract["shape"]),
                    tuple(int(value) for value in target_contract["stride"]),
                    int(target_contract["storage_offset"]),
                )
                expected_source_alias = _canonical_sha256(
                    {
                        "source": stage["source"],
                        "source_view_contract": dict(source_contract),
                    }
                )
                expected_target_alias = _canonical_sha256(
                    {
                        "target": stage["target"],
                        "target_view_contract": dict(target_contract),
                    }
                )
                if (
                    _tensor_contract(source) != dict(source_contract)
                    or _storage_pointer(source) != _storage_pointer(source_base)
                    or stage["source_alias_identity"] != expected_source_alias
                    or _tensor_contract(target) != dict(target_contract)
                    or _storage_pointer(target) != _storage_pointer(target_base)
                    or stage["target_alias_identity"] != expected_target_alias
                ):
                    raise GeneratedProgramDispatchError("prepared beta view identity differs")
                before_role = _nonempty_string(stage.get("before_role"), "prepared beta position")
                if before_role not in self._stage_roles:
                    raise GeneratedProgramDispatchError("prepared beta position is outside the device stages")
                actions.append((role, "before", before_role, target, source))
            elif role == "affine_torch_epilogue":
                after_role = _nonempty_string(stage.get("after_role"), "prepared affine position")
                if after_role != "affine_correction" or after_role not in self._stage_roles:
                    raise GeneratedProgramDispatchError("prepared affine position differs from production")
                actions.append(
                    (
                        role,
                        "after",
                        after_role,
                        *(
                            self._value(stage[name])
                            for name in (
                                "out_tail",
                                "correction_out",
                                "main_final",
                                "correction_final",
                                "final_compact",
                                "final_pool",
                                "state_indices_long",
                            )
                        ),
                    )
                )
            else:
                raise GeneratedProgramDispatchError(f"unknown prepared host role {role!r}")
        self._host_actions = tuple(actions)
        self._use_cuda_graph = topology != "single" or bool(host_stages)
        self._cuda_graph = None
        self._cuda_graph_capture_stream = None
        self._cuda_graph_warmed = False
        self._closed = False

    @property
    def route_id(self) -> str:
        return str(self._inner.route_id)

    @property
    def binding_facts(self) -> Mapping[str, Mapping[str, object]]:
        """Immutable pre-launch alias/layout facts for correctness assertions."""

        return self._binding_facts

    def _value(self, name: object) -> Any:
        key = _nonempty_string(name, "prepared host-stage binding")
        if key in self._tensors:
            return self._tensors[key]
        try:
            return self._workspaces[key]
        except KeyError as error:
            raise GeneratedProgramDispatchError(f"prepared host-stage binding {key!r} is unavailable") from error

    def _launch_uncaptured(self) -> None:
        import torch

        if not self._host_actions:
            self._inner.launch()
            return
        launch_stage = getattr(self._inner, "launch_stage", None)
        if not callable(launch_stage):
            raise GeneratedProgramDispatchError("prepared inner launch has no exact stage entrypoint")

        def perform(action: tuple[object, ...]) -> None:
            if action[0] == "beta_tma_refresh":
                action[3].copy_(action[4])
                return
            (
                _role,
                _position,
                _stage_role,
                out_tail,
                correction_out,
                main_final,
                correction_final,
                final_compact,
                final_pool,
                state_indices_long,
            ) = action
            out_tail.add_(correction_out)
            torch.add(
                main_final[-1:],
                correction_final[-1:],
                out=final_compact,
            )
            final_pool.index_copy_(
                0,
                state_indices_long,
                final_compact,
            )

        for stage_index, stage_role in enumerate(self._stage_roles):
            for action in self._host_actions:
                if action[1:3] == ("before", stage_role):
                    perform(action)
            launch_stage(stage_index)
            for action in self._host_actions:
                if action[1:3] == ("after", stage_role):
                    perform(action)

    def launch(self) -> None:
        if self._closed:
            raise RuntimeError("prepared KDA dispatch is closed")
        if not self._use_cuda_graph:
            self._launch_uncaptured()
            return

        import torch

        if torch.cuda.is_current_stream_capturing():
            self._launch_uncaptured()
            return
        if not self._cuda_graph_warmed:
            self._launch_uncaptured()
            self._cuda_graph_warmed = True
            return
        if self._cuda_graph is None:
            current_stream = torch.cuda.current_stream(self._device)
            capture_stream = torch.cuda.Stream(device=self._device)
            capture_stream.wait_stream(current_stream)
            capture_stream.synchronize()
            graph = torch.cuda.CUDAGraph()
            with torch.cuda.graph(graph, stream=capture_stream):
                self._launch_uncaptured()
            self._cuda_graph = graph
            self._cuda_graph_capture_stream = capture_stream
        self._cuda_graph.replay()

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        self._cuda_graph = None
        self._cuda_graph_capture_stream = None
        self._host_stages = ()
        self._host_actions = ()
        self._binding_facts = MappingProxyType({})
        self._stage_roles = ()
        self._tensors = {}
        self._workspaces = {}
        inner, self._inner = self._inner, None
        inner.close()



class _DirectPrepared:
    __slots__ = ("_calls", "_closed", "route_id")

    def __init__(self, row, modules, tensors, workspaces, scalars):
        self.route_id = str(row["id"])
        calls = []
        for stage in row["stages"]:
            artifact_id = stage["module"]
            entry = modules.get(artifact_id)
            if not callable(entry):
                raise GeneratedProgramDispatchError(
                    f"module {artifact_id!r} is unavailable or not callable"
                )
            args = tuple(
                _resolve_binding(binding, tensors, workspaces, scalars)
                for binding in stage["args"]
            )
            grid = tuple(
                _resolve_binding(binding, {}, {}, scalars)
                for binding in stage["grid"]
            )
            calls.append((entry, (*args, *grid)))
        self._calls = tuple(calls)
        self._closed = False

    def launch(self):
        if self._closed:
            raise RuntimeError("prepared direct KDA dispatch is closed")
        for entry, args in self._calls:
            entry(*args)

    def launch_stage(self, stage_index):
        if self._closed:
            raise RuntimeError("prepared direct KDA dispatch is closed")
        if isinstance(stage_index, bool) or not isinstance(stage_index, int):
            raise GeneratedProgramDispatchError("prepared direct stage index is invalid")
        if stage_index < 0 or stage_index >= len(self._calls):
            raise GeneratedProgramDispatchError("prepared direct stage index is out of range")
        entry, args = self._calls[stage_index]
        entry(*args)

    def close(self):
        if self._closed:
            return
        self._closed = True
        self._calls = ()


def _resolve_binding(binding, tensors, workspaces, scalars):
    kind = binding.get("kind") if isinstance(binding, Mapping) else None
    if kind == "literal":
        return binding["value"]
    name = binding.get("name") if isinstance(binding, Mapping) else None
    if kind == "tensor":
        return tensors[name]
    if kind == "workspace":
        return workspaces[name]
    if kind == "scalar":
        return scalars[name]
    if kind == "tensor_data_ptr":
        return int(tensors[name].data_ptr())
    raise GeneratedProgramDispatchError(f"unknown stage binding {kind!r}")


class _DirectLoader:
    ROUTE_IDS = tuple(str(row["id"]) for row in _CLOSURE["rows"])

    def __init__(self, modules):
        if tuple(modules) != FLASHINFER_MODULE_IDS:
            raise GeneratedProgramDispatchError("module map order differs from the sealed closure")
        if any(not callable(value) for value in modules.values()):
            raise GeneratedProgramDispatchError("module map contains a non-callable entry")
        self._modules = modules
        signature = _CLOSURE["signature"]
        self._tensor_names = tuple(field["name"] for field in signature["tensors"])
        self._scalar_names = tuple(field["name"] for field in signature["scalars"])
        self._workspace_names = tuple(field["name"] for field in signature["workspaces"])

    def prepare(self, *args, workspaces, arch):
        if arch != _CLOSURE["architecture"]:
            raise GeneratedProgramDispatchError("prepared architecture differs")
        expected = len(self._tensor_names) + len(self._scalar_names)
        if len(args) != expected or len(workspaces) != len(self._workspace_names):
            raise GeneratedProgramDispatchError("prepared direct ABI arity differs")
        tensors = dict(zip(self._tensor_names, args[:len(self._tensor_names)], strict=True))
        scalars = dict(zip(self._scalar_names, args[len(self._tensor_names):], strict=True))
        workspace_map = dict(zip(self._workspace_names, workspaces, strict=True))
        route_index = scalars.get(ROUTE_TAG)
        if isinstance(route_index, bool) or not isinstance(route_index, int):
            raise GeneratedProgramDispatchError("prepared route tag is invalid")
        if route_index < 0 or route_index >= len(_CLOSURE["rows"]):
            raise GeneratedProgramDispatchError("prepared route tag is unknown")
        row = _CLOSURE["rows"][route_index]
        return _DirectPrepared(row, self._modules, tensors, workspace_map, scalars)


class _ProgramAdapter:
    """Select and prepare through only the generated standalone family loader."""

    def __init__(
        self,
        closure: Mapping[str, object],
        *,
        selector: Callable[..., str],
        loader: Any,
    ) -> None:
        rows = closure.get("rows")
        if not isinstance(rows, list) or len(rows) != 48:
            raise GeneratedProgramDispatchError("portable adapter requires the closed 48-row denominator")
        self._architecture = _nonempty_string(closure.get("architecture"), "portable closure architecture")
        signature = _object(closure.get("signature"), {"tensors", "workspaces", "scalars"}, "signature")
        tensor_fields = _ordered_fields(signature["tensors"], "signature.tensors")
        workspace_fields = _ordered_fields(
            signature["workspaces"],
            "signature.workspaces",
            allow_empty=True,
        )
        scalar_fields = _ordered_fields(signature["scalars"], "signature.scalars", scalar=True)
        self._tensor_names = tuple(str(field["name"]) for field in tensor_fields)
        self._workspace_names = tuple(str(field["name"]) for field in workspace_fields)
        self._scalar_names = tuple(str(field["name"]) for field in scalar_fields)
        self._tensor_dtypes = {str(field["name"]): str(field["dtype"]) for field in tensor_fields}
        self._workspace_dtypes = {str(field["name"]): str(field["dtype"]) for field in workspace_fields}
        self._scalar_dtypes = {str(field["name"]): str(field["dtype"]) for field in scalar_fields}
        if ROUTE_TAG not in self._scalar_names:
            raise GeneratedProgramDispatchError(f"signature omits {ROUTE_TAG!r}")
        self._rows = {str(row["id"]): row for row in rows if isinstance(row, Mapping)}
        if len(self._rows) != 48:
            raise GeneratedProgramDispatchError("portable adapter row identities are invalid")
        expected_route_ids = tuple(str(row["id"]) for row in rows if isinstance(row, Mapping))
        if tuple(loader.ROUTE_IDS) != expected_route_ids:
            raise GeneratedProgramDispatchError("generated loader route inventory differs from frozen rows")
        self._selector = selector
        self._loader = loader

    def select(self, row_id: str, arguments: Mapping[str, object]) -> Mapping[str, object]:
        if set(arguments) != _SELECTOR_ARGUMENTS:
            raise GeneratedProgramDispatchError("portable selector arguments are incomplete")
        try:
            row = self._rows[row_id]
        except KeyError as error:
            raise GeneratedProgramDispatchError(f"unknown portable row {row_id!r}") from error
        if arguments["gpu_arch"] != self._architecture:
            raise GeneratedProgramDispatchError(f"{row_id}: selector architecture differs")
        frozen_facts = _object(
            row.get("selector_facts"),
            _SELECTOR_ARGUMENTS,
            f"{row_id}.selector_facts",
        )
        normalized_arguments = dict(arguments)
        normalized_arguments["sequence_lengths"] = list(arguments["sequence_lengths"])
        if normalized_arguments != dict(frozen_facts):
            raise GeneratedProgramDispatchError(f"{row_id}: selector facts differ from frozen row")
        route = self._selector(**arguments)
        if route != row["route"]:
            raise GeneratedProgramDispatchError(f"{row_id}: portable selector differs from frozen route")
        return row

    def _bind(
        self,
        row_id: str,
        *,
        selector_arguments: Mapping[str, object],
        tensors: Mapping[str, Any],
        scalars: Mapping[str, object],
        workspaces: Mapping[str, Any],
    ) -> _ProgramPrepared:
        row = self.select(row_id, selector_arguments)
        if set(tensors) != set(self._tensor_names):
            raise GeneratedProgramDispatchError(f"{row_id}: tensor closure differs")
        if set(workspaces) != set(self._workspace_names):
            raise GeneratedProgramDispatchError(f"{row_id}: workspace closure differs")
        caller_scalars = tuple(name for name in self._scalar_names if name != ROUTE_TAG)
        if set(scalars) != set(caller_scalars):
            raise GeneratedProgramDispatchError(f"{row_id}: scalar closure differs")
        route_tag = row["route_index"]
        ordered_scalars = [route_tag if name == ROUTE_TAG else scalars[name] for name in self._scalar_names]
        prepared = self._loader.prepare(
            *(tensors[name] for name in self._tensor_names),
            *ordered_scalars,
            workspaces=tuple(workspaces[name] for name in self._workspace_names),
            arch=self._architecture,
        )
        if prepared.route_id != row_id:
            prepared.close()
            raise GeneratedProgramDispatchError(f"{row_id}: compiled pinned route identity differs")
        host_stages = row.get("host_stages")
        if not isinstance(host_stages, list):
            prepared.close()
            raise GeneratedProgramDispatchError(f"{row_id}: host-stage closure is invalid")
        return _ProgramPrepared(
            prepared,
            topology=str(row["topology"]),
            host_stages=tuple(host_stages),
            tensors=tensors,
            workspaces=workspaces,
            binding_recipes={
                **dict(row["materialization"]["tensors"]),
                **dict(row["materialization"]["workspaces"]),
            },
        )

    def run(self, row_id: str, **prepare_arguments: Any) -> None:
        """Convenience call with the canonical prepare/launch/finally-close flow."""

        prepared = self.prepare(row_id, **prepare_arguments)
        try:
            prepared.launch()
        finally:
            prepared.close()

    @staticmethod
    def _verify_derivation(
        recipe: Mapping[str, object],
        semantic_facts: Mapping[str, object],
        semantic_tensors: Mapping[str, Any],
    ) -> None:
        derivation = _object(
            recipe.get("derivation"),
            {"id", "roots"},
            "materialization derivation",
        )
        if derivation["id"] != "production-prepared-fixed-row-v1":
            raise GeneratedProgramDispatchError("materialization derivation identity differs")
        roots = derivation["roots"]
        if not isinstance(roots, list) or not roots:
            raise GeneratedProgramDispatchError("materialization derivation roots are empty")
        expected_names: set[str] = set()
        for index, raw_root in enumerate(roots):
            if not isinstance(raw_root, Mapping):
                raise GeneratedProgramDispatchError(f"materialization root[{index}] is not an object")
            kind = raw_root.get("kind")
            if kind == "value":
                root = _object(
                    raw_root,
                    {"kind", "name", "sha256"},
                    f"materialization root[{index}]",
                )
                name = _nonempty_string(root["name"], f"materialization root[{index}].name")
                if name not in semantic_facts or _canonical_sha256(semantic_facts[name]) != root["sha256"]:
                    raise GeneratedProgramDispatchError(
                        f"semantic fact {name!r} content differs from materialization derivation"
                    )
            elif kind == "tensor_content":
                root = _object(
                    raw_root,
                    {"kind", "name", "source", "contract", "sha256"},
                    f"materialization root[{index}]",
                )
                name = _nonempty_string(root["name"], f"materialization root[{index}].name")
                source = _nonempty_string(root["source"], f"materialization root[{index}].source")
                try:
                    tensor = semantic_tensors[source]
                except KeyError as error:
                    raise GeneratedProgramDispatchError(
                        f"semantic tensor content root {source!r} is unavailable"
                    ) from error
                if _tensor_contract(tensor) != root["contract"] or _tensor_content_sha256(tensor) != root["sha256"]:
                    raise GeneratedProgramDispatchError(
                        f"semantic tensor {source!r} content differs from materialization derivation"
                    )
            else:
                raise GeneratedProgramDispatchError(f"materialization root[{index}] has unsupported kind {kind!r}")
            if name in expected_names:
                raise GeneratedProgramDispatchError(f"materialization derivation duplicates root {name!r}")
            expected_names.add(name)
        value_names = {str(root["name"]) for root in roots if isinstance(root, Mapping) and root.get("kind") == "value"}
        if set(semantic_facts) != value_names:
            raise GeneratedProgramDispatchError("semantic fact denominator differs from materialization derivation")

    @classmethod
    def _materialize_recipe(
        cls,
        recipe: object,
        *,
        semantic_tensors: Mapping[str, Any],
        semantic_facts: Mapping[str, object],
        device: Any,
    ) -> Any:
        import torch

        if not isinstance(recipe, Mapping):
            raise GeneratedProgramDispatchError("materialization recipe is not an object")
        op = recipe.get("op")
        if op == "semantic_view":
            view = _object(
                recipe,
                {"op", "source", "source_contract", "view_contract", "alias_identity"},
                "semantic view recipe",
            )
            source_name = _nonempty_string(view["source"], "semantic view source")
            try:
                source = semantic_tensors[source_name]
            except KeyError as error:
                raise GeneratedProgramDispatchError(f"semantic view source {source_name!r} is unavailable") from error
            if _tensor_contract(source) != view["source_contract"]:
                raise GeneratedProgramDispatchError(f"semantic tensor {source_name!r} contract differs")
            contract = _object(
                view["view_contract"],
                {"dtype", "shape", "stride", "storage_offset"},
                "semantic view contract",
            )
            source_span = _storage_span(view["source_contract"])
            view_span = _storage_span(contract)
            if (view_span is not None and source_span is None) or (
                view_span is not None
                and source_span is not None
                and (view_span[0] < source_span[0] or view_span[1] > source_span[1])
            ):
                raise GeneratedProgramDispatchError("semantic view escapes its source")
            result = source.as_strided(
                tuple(int(value) for value in contract["shape"]),
                tuple(int(value) for value in contract["stride"]),
                int(contract["storage_offset"]),
            )
            if _tensor_contract(result) != dict(contract) or _storage_pointer(result) != _storage_pointer(source):
                raise GeneratedProgramDispatchError("semantic view alias contract differs after materialization")
            expected_alias = _canonical_sha256(
                {
                    "source": source_name,
                    "source_contract": view["source_contract"],
                    "view_contract": view["view_contract"],
                }
            )
            if view["alias_identity"] != expected_alias:
                raise GeneratedProgramDispatchError("semantic view alias identity differs")
            return result
        expected_fields = {"op", "dtype", "shape", "stride", "storage_offset", "derivation"}
        if op == "snapshot":
            expected_fields.add("values")
        if op == "unused":
            expected_fields.add("proof")
        typed = _object(recipe, expected_fields, "workspace recipe")
        if op not in {"unused", "empty", "zeros", "batched_identity", "snapshot"}:
            raise GeneratedProgramDispatchError(f"unsupported materialization op {op!r}")
        cls._verify_derivation(typed, semantic_facts, semantic_tensors)
        dtype_name = _nonempty_string(typed["dtype"], "workspace recipe dtype")
        dtype = getattr(torch, dtype_name, None)
        if dtype is None:
            raise GeneratedProgramDispatchError(f"workspace dtype {dtype_name!r} is unavailable")
        shape = tuple(int(value) for value in typed["shape"])
        stride = tuple(int(value) for value in typed["stride"])
        if int(typed["storage_offset"]) != 0:
            raise GeneratedProgramDispatchError("workspace recipe storage offset is not materializable")
        if op in {"unused", "empty"}:
            result = torch.empty_strided(shape, stride, dtype=dtype, device=device)
        elif op == "zeros":
            result = torch.empty_strided(shape, stride, dtype=dtype, device=device)
            result.zero_()
        elif op == "batched_identity":
            if (
                len(shape) < 2
                or shape[-2] != shape[-1]
                or dtype
                not in {
                    torch.bfloat16,
                    torch.float32,
                }
            ):
                raise GeneratedProgramDispatchError("identity workspace contract is invalid")
            source = torch.eye(shape[-1], dtype=dtype, device=device).expand(shape)
            result = torch.empty_strided(shape, stride, dtype=dtype, device=device)
            result.copy_(source)
        else:
            source = torch.tensor(typed["values"], dtype=dtype, device=device).reshape(shape)
            result = torch.empty_strided(shape, stride, dtype=dtype, device=device)
            result.copy_(source)
        expected_contract = {
            "dtype": dtype_name,
            "shape": list(shape),
            "stride": [int(value) for value in typed["stride"]],
            "storage_offset": int(typed["storage_offset"]),
        }
        if _tensor_contract(result) != expected_contract:
            raise GeneratedProgramDispatchError("materialized workspace layout differs from captured contract")
        return result

    def prepare(
        self,
        row_id: str,
        *,
        selector_arguments: Mapping[str, object],
        semantic_tensors: Mapping[str, Any],
        semantic_facts: Mapping[str, object],
        invocation_scalars: Mapping[str, int | float],
    ) -> _ProgramPrepared:
        """Rebuild one fixed-row closure, then enter only the generated loader."""

        row = self.select(row_id, selector_arguments)
        materialization = _object(
            row.get("materialization"),
            {"tensors", "workspaces", "scalars"},
            f"{row_id}.materialization",
        )
        if not semantic_tensors:
            raise GeneratedProgramDispatchError(f"{row_id}: semantic tensor roots are empty")
        first = next(iter(semantic_tensors.values()))
        device = first.device
        tensor_recipes = materialization["tensors"]
        workspace_recipes = materialization["workspaces"]
        scalar_values = materialization["scalars"]
        if not all(isinstance(value, Mapping) for value in (tensor_recipes, workspace_recipes, scalar_values)):
            raise GeneratedProgramDispatchError(f"{row_id}: materialization maps are invalid")
        if set(tensor_recipes) != set(self._tensor_names):
            raise GeneratedProgramDispatchError(f"{row_id}: tensor recipe denominator differs")
        if set(workspace_recipes) != set(self._workspace_names):
            raise GeneratedProgramDispatchError(f"{row_id}: workspace recipe denominator differs")
        expected_scalar_names = {name for name in self._scalar_names if name != ROUTE_TAG}
        if set(scalar_values) != expected_scalar_names:
            raise GeneratedProgramDispatchError(f"{row_id}: scalar recipe denominator differs")
        tensors: dict[str, Any] = {}
        for name in self._tensor_names:
            tensors[name] = self._materialize_recipe(
                tensor_recipes[name],
                semantic_tensors=semantic_tensors,
                semantic_facts=semantic_facts,
                device=device,
            )
        workspaces: dict[str, Any] = {}
        for name in self._workspace_names:
            workspaces[name] = self._materialize_recipe(
                workspace_recipes[name],
                semantic_tensors=semantic_tensors,
                semantic_facts=semantic_facts,
                device=device,
            )
        scalars: dict[str, int | float] = {}
        consumed_scalar_sources: set[str] = set()
        for name in self._scalar_names:
            if name == ROUTE_TAG:
                continue
            recipe = _object(
                scalar_values[name],
                {"op", "source", "dtype"},
                f"{row_id}.materialization.scalars.{name}",
            )
            if recipe["op"] != "invocation_scalar" or recipe["dtype"] != self._scalar_dtypes[name]:
                raise GeneratedProgramDispatchError(f"{row_id}: scalar {name!r} recipe differs")
            source = _nonempty_string(recipe["source"], f"{row_id}.scalar.{name}.source")
            try:
                value = invocation_scalars[source]
            except KeyError as error:
                raise GeneratedProgramDispatchError(
                    f"{row_id}: invocation scalar source {source!r} is unavailable"
                ) from error
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise GeneratedProgramDispatchError(f"{row_id}: invocation scalar {source!r} is invalid")
            if self._scalar_dtypes[name].startswith("float") != isinstance(value, float):
                raise GeneratedProgramDispatchError(f"{row_id}: invocation scalar {source!r} type differs")
            consumed_scalar_sources.add(source)
            scalars[name] = value
        if set(invocation_scalars) != consumed_scalar_sources:
            raise GeneratedProgramDispatchError(f"{row_id}: invocation scalar denominator differs")
        return self._bind(
            row_id,
            selector_arguments=selector_arguments,
            tensors=tensors,
            scalars=scalars,
            workspaces=workspaces,
        )



class Prepared:
    __slots__ = ("_closed", "_inner", "_output", "_return_state", "_state_pool")

    def __init__(self, inner, output, state_pool, return_state):
        self._inner = inner
        self._output = output
        self._state_pool = state_pool
        self._return_state = return_state
        self._closed = False

    def launch(self):
        if self._closed:
            raise RuntimeError("prepared public KDA dispatch is closed")
        self._inner.launch()
        return self._output, self._state_pool if self._return_state else None

    def close(self):
        if self._closed:
            return
        self._closed = True
        inner, self._inner = self._inner, None
        self._output = None
        self._state_pool = None
        inner.close()


def _activity_contract(row):
    host_roles = [stage.get("role") for stage in row["host_stages"]]
    if any(role not in {"beta_tma_refresh", "affine_torch_epilogue"} for role in host_roles):
        raise GeneratedProgramDispatchError("unknown public host activity role")
    module_roles = [module.get("role") for module in row["modules"]]
    if any(not isinstance(role, str) or not role for role in module_roles):
        raise GeneratedProgramDispatchError("unknown public module activity role")
    segments = [{"activity_count": 0, "fixed_markers": []} for _ in range(len(module_roles) + 1)]
    for stage in row["host_stages"]:
        if stage["role"] == "beta_tma_refresh":
            before_role = stage.get("before_role")
            if before_role not in module_roles:
                raise GeneratedProgramDispatchError("unknown public beta activity position")
            segment = segments[module_roles.index(before_role)]
            segment["activity_count"] += 1
            segment["fixed_markers"].append("direct_copy_kernel_cuda")
        else:
            after_role = stage.get("after_role")
            if after_role not in module_roles:
                raise GeneratedProgramDispatchError("unknown public affine activity position")
            segments[module_roles.index(after_role) + 1]["activity_count"] += 3
    return {
        "device_kernel_names": [module["kernel_name"] for module in row["modules"]],
        "host_roles": host_roles,
        "expected_host_activity_count": host_roles.count("beta_tma_refresh")
        + 3 * host_roles.count("affine_torch_epilogue"),
        "expected_fixed_host_activity_markers": [
            "direct_copy_kernel_cuda" for role in host_roles if role == "beta_tma_refresh"
        ],
        "expected_activity_segments": segments,
    }


def _validate_closure():
    if _CLOSURE.get("schema_version") != 1:
        raise GeneratedProgramDispatchError("public closure schema differs")
    if _CLOSURE.get("public_binding_contract") != _PUBLIC_BINDING_CONTRACT:
        raise GeneratedProgramDispatchError("public binding contract differs")
    rows = _CLOSURE.get("rows")
    if not isinstance(rows, list) or len(rows) != 48:
        raise GeneratedProgramDispatchError("public row denominator differs")
    counts = {"single": 0, "bt16": 0, "affine": 0}
    expected_roles = {
        "single": ("main",),
        "bt16": ("prepare", "main"),
        "affine": ("affine_main", "affine_map", "affine_scan", "affine_correction"),
    }
    for index, row in enumerate(rows):
        topology = row.get("topology")
        if row.get("route_index") != index or topology not in expected_roles:
            raise GeneratedProgramDispatchError("unknown or unordered public row")
        counts[topology] += 1
        roles = expected_roles[topology]
        if tuple(module.get("role") for module in row["modules"]) != roles:
            raise GeneratedProgramDispatchError("unknown public module role")
        if tuple(stage.get("role") for stage in row["stages"]) != roles:
            raise GeneratedProgramDispatchError("unknown public stage role")
        if row.get("public_activity_contract") != _activity_contract(row):
            raise GeneratedProgramDispatchError("unknown public activity contract")
    if counts != {"single": 32, "bt16": 9, "affine": 7}:
        raise GeneratedProgramDispatchError("public topology denominator differs")


_validate_closure()


def _selector_facts(q, cu_seqlens):
    import torch
    if not isinstance(q, torch.Tensor) or q.ndim != 4 or int(q.shape[3]) != 128:
        raise GeneratedProgramDispatchError("q must have shape [B,T,H,128]")
    capability = tuple(int(value) for value in torch.cuda.get_device_capability(q.device))
    gpu_arch = {(10, 0): "sm_100a", (10, 3): "sm_103a"}.get(capability)
    if gpu_arch is None:
        raise GeneratedProgramDispatchError(f"unsupported compute capability {capability!r}")
    sm_count = int(torch.cuda.get_device_properties(q.device).multi_processor_count)
    batch, tokens, heads, _ = (int(value) for value in q.shape)
    if cu_seqlens is None:
        fixed_layout = True
        sequence_lengths = (tokens,) * batch
    else:
        fixed_layout = False
        offsets = tuple(int(value) for value in cu_seqlens.detach().cpu().tolist())
        if len(offsets) < 2 or offsets[0] != 0 or offsets[-1] != batch * tokens:
            raise GeneratedProgramDispatchError("packed cu_seqlens endpoints differ")
        sequence_lengths = tuple(end - start for start, end in zip(offsets, offsets[1:]))
        if any(value <= 0 for value in sequence_lengths):
            raise GeneratedProgramDispatchError("packed sequence lengths are invalid")
    return {
        "gpu_arch": gpu_arch,
        "sm_count": sm_count,
        "fixed_layout": fixed_layout,
        "sequence_lengths": sequence_lengths,
        "num_heads": heads,
        "use_initial_state": True,
        "store_final_state": True,
    }


def _select_row(**arguments):
    if set(arguments) != set(_SELECTOR_ARGUMENTS):
        raise GeneratedProgramDispatchError("selector argument denominator differs")
    normalized = dict(arguments)
    normalized["sequence_lengths"] = list(arguments["sequence_lengths"])
    matches = [row for row in _CLOSURE["rows"] if row["selector_facts"] == normalized]
    if len(matches) != 1:
        state = "unknown" if not matches else "ambiguous"
        raise GeneratedProgramDispatchError(f"{state} public selector row")
    return matches[0]


def _validate_public_arguments(*, q, k, v, g, beta, A_log, dt_bias, scale,
                               initial_state, output_final_state, lower_bound,
                               cu_seqlens, output, seq_order, prefill_workspace,
                               state_indices, state_checkpoints, checkpoint_cu_starts,
                               checkpoint_every_n_tokens):
    import torch
    if type(output_final_state) is not bool:
        raise GeneratedProgramDispatchError("output_final_state must be bool")
    if seq_order is not None or prefill_workspace is not None:
        raise GeneratedProgramDispatchError("external prefill workspace arguments must be None")
    if state_checkpoints is not None or checkpoint_cu_starts is not None or checkpoint_every_n_tokens != 0:
        raise GeneratedProgramDispatchError("checkpoint mode is unsupported")
    required = (q, k, v, g, beta, A_log, dt_bias, initial_state, output, state_indices)
    if any(not isinstance(value, torch.Tensor) for value in required):
        raise GeneratedProgramDispatchError("public tensor denominator is incomplete")
    if initial_state.dtype != torch.float32 or state_indices.dtype != torch.int32:
        raise GeneratedProgramDispatchError("indexed state dtype contract differs")
    if output.numel() == 0:
        raise GeneratedProgramDispatchError("output must be preallocated")
    if scale is None:
        scale = 1.0 / math.sqrt(128.0)
    if isinstance(scale, bool) or not isinstance(scale, (int, float)) or not math.isfinite(float(scale)):
        raise GeneratedProgramDispatchError("scale must be finite")
    if isinstance(lower_bound, bool) or not isinstance(lower_bound, (int, float)):
        raise GeneratedProgramDispatchError("lower_bound must be numeric")
    lower_bound = float(lower_bound)
    if not math.isfinite(lower_bound) or not -5.0 <= lower_bound <= 0.0:
        raise GeneratedProgramDispatchError("lower_bound is outside [-5, 0]")
    return float(scale), lower_bound


def bind_loaded_modules(modules):
    loader = _DirectLoader(modules)
    adapter = _ProgramAdapter(_CLOSURE, selector=lambda **facts: _select_row(**facts)["route"], loader=loader)

    def select_fp32_indexed_schedule_route(*, gpu_arch, sm_count, fixed_layout,
                                           sequence_lengths, num_heads,
                                           use_initial_state, store_final_state):
        return _select_row(
            gpu_arch=gpu_arch,
            sm_count=sm_count,
            fixed_layout=fixed_layout,
            sequence_lengths=sequence_lengths,
            num_heads=num_heads,
            use_initial_state=use_initial_state,
            store_final_state=store_final_state,
        )["route"]

    def prepare_fwd(*, q, k, v, g, beta, A_log, dt_bias, scale, initial_state,
                    output_final_state, lower_bound, cu_seqlens, output, seq_order,
                    prefill_workspace, state_indices, state_checkpoints,
                    checkpoint_cu_starts, checkpoint_every_n_tokens):
        scale_value, lower_bound_value = _validate_public_arguments(
            q=q, k=k, v=v, g=g, beta=beta, A_log=A_log, dt_bias=dt_bias,
            scale=scale, initial_state=initial_state,
            output_final_state=output_final_state, lower_bound=lower_bound,
            cu_seqlens=cu_seqlens, output=output, seq_order=seq_order,
            prefill_workspace=prefill_workspace, state_indices=state_indices,
            state_checkpoints=state_checkpoints,
            checkpoint_cu_starts=checkpoint_cu_starts,
            checkpoint_every_n_tokens=checkpoint_every_n_tokens,
        )
        selector_facts = _selector_facts(q, cu_seqlens)
        if selector_facts["gpu_arch"] != _CLOSURE["architecture"]:
            raise GeneratedProgramDispatchError("runtime architecture differs from closure")
        row = _select_row(**selector_facts)
        semantic_tensors = {
            "q": q, "k": k, "v": v, "g": g, "beta": beta,
            "A_log": A_log, "dt_bias": dt_bias, "state_pool": initial_state,
            "state_indices": state_indices, "out": output,
        }
        if cu_seqlens is not None:
            semantic_tensors["cu_seqlens"] = cu_seqlens
        semantic_facts = {
            "architecture": selector_facts["gpu_arch"],
            "sm_count": selector_facts["sm_count"],
            "heads": selector_facts["num_heads"],
            "layout": "fixed" if selector_facts["fixed_layout"] else "packed_varlen",
            "sequence_lengths": list(selector_facts["sequence_lengths"]),
            "state_pool_capacity": int(initial_state.shape[0]),
        }
        public_scalars = {"scale": scale_value, "lower_bound": lower_bound_value}
        scalar_recipes = row["materialization"]["scalars"]
        if not isinstance(scalar_recipes, Mapping) or any(
            not isinstance(recipe, Mapping) for recipe in scalar_recipes.values()
        ):
            raise GeneratedProgramDispatchError("public scalar recipe closure is invalid")
        scalar_sources = {recipe.get("source") for recipe in scalar_recipes.values()}
        if not scalar_sources <= set(public_scalars):
            raise GeneratedProgramDispatchError("public scalar source is unknown")
        inner = adapter.prepare(
            row["id"],
            selector_arguments=selector_facts,
            semantic_tensors=semantic_tensors,
            semantic_facts=semantic_facts,
            invocation_scalars={name: public_scalars[name] for name in scalar_sources},
        )
        return Prepared(inner, output, initial_state, output_final_state)

    return {
        "select_fp32_indexed_schedule_route": select_fp32_indexed_schedule_route,
        "prepare_fwd": prepare_fwd,
    }
